package com.infiniticonnect.demo;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.text.SimpleDateFormat;
import java.util.*;

public class MainActivity extends Activity {
 final int BG=0xff0b0f15, PANEL=0xff18202b, ACCENT=0xffc7a768, TEXT=0xfff3f5f7, MUTED=0xffaab5c2;
 LinearLayout page,root; android.content.SharedPreferences prefs;
 String model="Q50S Facelift",paint="Metallic-Grau",tab="Übersicht";
 int temp=22,fan=2,odo=84500,serviceAt=75000,interval=15000;
 boolean climate=false,seat=false,windows=false;
 String[] models={"Q50 Vorfacelift","Q50 Facelift","Q50S Facelift","Q60"};
 String[] paints={"Metallic-Grau","Schwarz","Weiß","Silber","Blau","Rot"};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);prefs=getSharedPreferences("infiniti",0);model=prefs.getString("model",model);paint=prefs.getString("paint",paint);odo=prefs.getInt("odo",odo);serviceAt=prefs.getInt("serviceAt",serviceAt);interval=prefs.getInt("interval",interval);temp=prefs.getInt("temp",temp);fan=prefs.getInt("fan",fan);climate=prefs.getBoolean("climate",false);show("Übersicht");}
 void save(){prefs.edit().putString("model",model).putString("paint",paint).putInt("odo",odo).putInt("serviceAt",serviceAt).putInt("interval",interval).putInt("temp",temp).putInt("fan",fan).putBoolean("climate",climate).apply();}
 GradientDrawable shape(int color,int rad){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(rad);return d;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,6,0,6);return t;}
 void heading(String s){TextView t=text(s,20,TEXT);t.setTypeface(null,Typeface.BOLD);page.addView(t);}
 LinearLayout card(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(20,16,20,16);l.setBackground(shape(PANEL,24));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,9,0,9);page.addView(l,lp);return l;}
 void field(LinearLayout c,String label,String value){c.addView(text(label,13,MUTED));TextView v=text(value,20,TEXT);v.setTypeface(null,Typeface.BOLD);c.addView(v);}
 void button(LinearLayout into,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(TEXT);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff303c4c));into.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->action.run());}
 void notice(String msg){new AlertDialog.Builder(this).setTitle("Demo-Modus").setMessage(msg+"\n\nEs wurde kein Befehl an das Fahrzeug gesendet.").setPositiveButton("OK",null).show();}
 void show(String selected){tab=selected;root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(BG);setContentView(root);TextView title=text("  INFINITI CONNECT",23,ACCENT);title.setTypeface(null,Typeface.BOLD);title.setPadding(16,18,8,4);root.addView(title);TextView demo=text("  DEMO · Keine Fahrzeugverbindung",12,MUTED);root.addView(demo);HorizontalScrollView nav=new HorizontalScrollView(this);LinearLayout bar=new LinearLayout(this);bar.setPadding(5,7,5,7);nav.addView(bar);for(String s:new String[]{"Übersicht","Garage","Steuerung","Fahrten","Diagnose","Wartung","Einstellungen"}){Button b=new Button(this);b.setText(s);b.setTextSize(11);b.setAllCaps(false);b.setTextColor(s.equals(tab)?ACCENT:TEXT);bar.addView(b);b.setOnClickListener(v->show(s));}root.addView(nav);ScrollView scroll=new ScrollView(this);page=new LinearLayout(this);page.setPadding(18,10,18,35);page.setOrientation(1);scroll.addView(page);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));switch(tab){case "Übersicht":overview();break;case "Garage":garage();break;case "Steuerung":controls();break;case "Fahrten":trips();break;case "Diagnose":diagnosis();break;case "Wartung":maintenance();break;default:settings();}}
 void overview(){heading(model);LinearLayout c=card();c.addView(new CarView(this,paint));field(c,"Lackierung",paint);LinearLayout d=card();field(d,"Kilometerstand",String.format(Locale.GERMANY,"%,d km",odo));field(d,"Tankfüllstand (Demo)","68 %");field(d,"Restreichweite (Demo)","487 km");field(d,"Ø Verbrauch (Demo)","7,2 l/100 km");LinearLayout h=card();field(h,"Hybridbatterie (Demo)","62 %");field(h,"12-V-Batterie (Demo)","12,6 V");LinearLayout p=card();field(p,"Reifendruck vorne links / rechts (Demo)","2,4 / 2,4 bar");field(p,"Reifendruck hinten links / rechts (Demo)","2,5 / 2,5 bar");LinearLayout w=card();field(w,"Nächster Service",Math.max(0,serviceAt+interval-odo)+" km verbleibend");button(w,"Wartung öffnen",()->show("Wartung"));}
 void garage(){heading("Fahrzeugauswahl");LinearLayout c=card();c.addView(new CarView(this,paint));field(c,"Ausgewählt",model+" · "+paint);c.addView(text("Stilisierte Fahrzeugvorschau (keine Modellfotografie)",12,MUTED));spinner(c,"Modell",models,model,s->{model=s;save();show("Garage");});spinner(c,"Farbe",paints,paint,s->{paint=s;save();show("Garage");});}
 interface Choose{void chosen(String s);}
 void spinner(LinearLayout c,String label,String[] opts,String current,Choose callback){c.addView(text(label,14,MUTED));Spinner sp=new Spinner(this);ArrayAdapter<String> a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,opts);sp.setAdapter(a);sp.setSelection(Arrays.asList(opts).indexOf(current));c.addView(sp);sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){boolean init=false;public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){if(!init){init=true;return;}callback.chosen(opts[pos]);}});}
 void controls(){heading("Fahrzeugsteuerung · Simulation");LinearLayout c=card();field(c,"Klimaanlage",climate?"Ein":"Aus");button(c,climate?"Klimaanlage ausschalten":"Klimaanlage einschalten",()->{climate=!climate;save();show("Steuerung");});field(c,"Solltemperatur",temp+" °C");SeekBar t=new SeekBar(this);t.setMax(14);t.setProgress(temp-16);c.addView(t);t.setOnSeekBarChangeListener(listener(v->{temp=16+v;save();show("Steuerung");}));field(c,"Gebläsestufe",fan+" / 7");SeekBar f=new SeekBar(this);f.setMax(7);f.setProgress(fan);c.addView(f);f.setOnSeekBarChangeListener(listener(v->{fan=v;save();show("Steuerung");}));button(c,"Luftverteilung wählen",()->new AlertDialog.Builder(this).setItems(new String[]{"Frontscheibe","Oberkörper","Fußraum","Automatisch"},(d,which)->notice("Luftverteilung: "+new String[]{"Frontscheibe","Oberkörper","Fußraum","Automatisch"}[which])).show());LinearLayout x=card();field(x,"Fenster",windows?"Demo: geöffnet":"Demo: geschlossen");button(x,windows?"Fenster schließen":"Fenster öffnen",()->{windows=!windows;show("Steuerung");});field(x,"Sitzheizung",seat?"Demo: Ein":"Demo: Aus");button(x,"Sitzheizung umschalten",()->{seat=!seat;show("Steuerung");});}
 interface Changed{void change(int v);}
 SeekBar.OnSeekBarChangeListener listener(Changed c){return new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){c.change(b.getProgress());}public void onProgressChanged(SeekBar b,int p,boolean u){}};}
 void trips(){heading("Fahrtenbuch");LinearLayout c=card();field(c,"Demo-Fahrten",prefs.getInt("trips",3)+" Einträge");for(int i=0;i<3;i++){LinearLayout row=card();field(row,"Beispielfahrt "+(i+1),new String[]{"24,6 km · 7,1 l/100 km","18,3 km · 6,8 l/100 km","42,1 km · 7,5 l/100 km"}[i]);}button(c,"Simulierte Fahrt hinzufügen",()->{prefs.edit().putInt("trips",prefs.getInt("trips",3)+1).apply();show("Fahrten");});button(c,"Fahrten zurücksetzen",()->{prefs.edit().putInt("trips",3).apply();show("Fahrten");});}
 void diagnosis(){heading("Fahrzeugdiagnose");LinearLayout c=card();field(c,"Verbindung","Nicht verbunden");field(c,"Fehlercodes","Keine echten Messdaten verfügbar");button(c,"Diagnose simulieren",()->notice("Demo-Scan abgeschlossen: keine realen Steuergeräte ausgelesen."));button(c,"Fehlerspeicher löschen (Demo)",()->notice("Nur eine Demo: Es wurden keine Fehlercodes gelöscht."));}
 void maintenance(){heading("Wartung & Service");LinearLayout c=card();field(c,"Nächster Service bei",(serviceAt+interval)+" km");field(c,"Reststrecke",(serviceAt+interval-odo)+" km");editNumber(c,"Letzter Service (km)",serviceAt,v->{serviceAt=v;save();show("Wartung");});editNumber(c,"Serviceintervall (km)",interval,v->{interval=v;save();show("Wartung");});button(c,"Service bei aktuellem Kilometerstand eintragen",()->{serviceAt=odo;save();prefs.edit().putString("history",new SimpleDateFormat("dd.MM.yyyy",Locale.GERMANY).format(new Date())+" · "+odo+" km\n"+prefs.getString("history","")).apply();show("Wartung");});LinearLayout h=card();h.addView(text("Servicehistorie",17,TEXT));h.addView(text(prefs.getString("history","Noch keine Wartung eingetragen"),14,MUTED));}
 interface NumberChanged{void changed(int n);}
 void editNumber(LinearLayout c,String label,int current,NumberChanged action){c.addView(text(label,14,MUTED));EditText e=new EditText(this);e.setInputType(2);e.setText(""+current);e.setTextColor(TEXT);c.addView(e);button(c,"Speichern: "+label,()->{try{int v=Integer.parseInt(e.getText().toString());if(v<0)throw new Exception();action.changed(v);}catch(Exception ex){Toast.makeText(this,"Bitte gültige Zahl eingeben",Toast.LENGTH_SHORT).show();}});}
 void settings(){heading("Einstellungen");LinearLayout c=card();editNumber(c,"Kilometerstand (Demo)",odo,v->{odo=v;save();show("Einstellungen");});button(c,"Fahrzeug auswählen",()->show("Garage"));button(c,"Homescreen-Widget hinzufügen",()->notice("Widget über Android-Homescreen > Widgets > Infiniti Connect hinzufügen. Es zeigt Demo-Werte."));button(c,"Synchronisierung testen",()->notice("Keine Aucar- oder OBD-Verbindung vorhanden."));}
 static class CarView extends View{String paint;CarView(Context c,String p){super(c);paint=p;setMinimumHeight(210);}protected void onMeasure(int w,int h){setMeasuredDimension(MeasureSpec.getSize(w),210);}protected void onDraw(android.graphics.Canvas c){super.onDraw(c);int color=0xff777e87;switch(paint){case "Schwarz":color=0xff272b32;break;case "Weiß":color=0xffe5e7e9;break;case "Silber":color=0xffa9b0b9;break;case "Blau":color=0xff284f8b;break;case "Rot":color=0xffa32b34;break;}android.graphics.Paint p=new android.graphics.Paint(3);float sx=getWidth()/340f;c.save();c.scale(sx,1);p.setColor(0xff0c1119);c.drawRoundRect(0,20,340,195,20,20,p);p.setColor(color);c.drawRoundRect(30,96,312,160,24,24,p);android.graphics.Path roof=new android.graphics.Path();roof.moveTo(92,102);roof.lineTo(139,66);roof.lineTo(236,66);roof.lineTo(274,102);roof.close();c.drawPath(roof,p);p.setColor(0xff253e50);c.drawRoundRect(145,72,232,100,8,8,p);c.drawRoundRect(107,72,139,100,8,8,p);p.setColor(0xff10141a);c.drawCircle(92,160,29,p);c.drawCircle(264,160,29,p);p.setColor(0xffaab5bf);c.drawCircle(92,160,15,p);c.drawCircle(264,160,15,p);p.setColor(0xfff4e8c7);c.drawRect(294,116,310,124,p);c.restore();}}
}
